/** Opt-in, additive presentation records. Never called by a public page or installer. */
function demo_data_admin(): array {
 $u=require_permission('settings.manage');
 if($u['role']!=='admin')abort_page(403,'Only the primary administrator role can load demonstration records.');
 return $u;
}
function demo_data_manifest(): ?array {
 $r=row('SELECT setting_value FROM settings WHERE setting_key=?',['demo_dataset_v103']);
 if(!$r)return null;
 $manifest=json_decode($r['setting_value'],true,512,JSON_THROW_ON_ERROR);
 return is_array($manifest)?$manifest:null;
}
function demo_data_page(): void {
 $u=demo_data_admin();$manifest=demo_data_manifest();
 if(($_GET['export']??'')==='accounts'){
  if(!$manifest)abort_page(404,'Load the demonstration records before exporting the account directory.');
  header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="CivicFlow_Demonstration_Accounts.csv"');
  $out=fopen('php://output','wb');fputcsv($out,['Name','Email','Role','Department','Password']);
  foreach($manifest['user_ids']as $id){$account=row('SELECT u.name,u.email,u.role,d.name department FROM users u LEFT JOIN departments d ON d.id=u.department_id WHERE u.id=?',[$id]);if($account)fputcsv($out,array_map(fn($cell)=>preg_match('/^[\s]*[=+@-]/u',(string)$cell)?"'".$cell:$cell,[$account['name'],$account['email'],label($account['role']),$account['department']?:'Not department-scoped','Chosen by the administrator when loading; not stored in plain text']));}
  fclose($out);exit;
 }
