function demo_data_post(): never {
 $u=demo_data_admin();rate_limit('demo-load:'.$u['id'],12,3600);
 $lock=fopen(ROOT.'/storage/cache/demo-data.lock','c+');
 if(!$lock||!flock($lock,LOCK_EX|LOCK_NB)){if(is_resource($lock))fclose($lock);throw new InvalidArgumentException('A demonstration load is already running. Wait a moment and reload this page.');}
 try{
  if(demo_data_manifest()){flash('Demonstration records are already loaded. No duplicate accounts or cases were added.');}
  else{
   $password=(string)($_POST['demo_password']??'');password_valid($password);
   if(!hash_equals($password,(string)($_POST['demo_password_confirm']??'')))throw new InvalidArgumentException('The demonstration passwords do not match.');
   if(($_POST['confirm_demo']??'')!=='1')throw new InvalidArgumentException('Confirm demonstration mode and publication of the starter services.');
   demo_data_seed($password,$u);flash('The demonstration dataset is ready: 26 accounts, 36 cases and all 6 roles. Your administrator password is unchanged.');
  }
 }finally{flock($lock,LOCK_UN);fclose($lock);}
 go('admin/demo-data');
}
function demo_pdf_bytes(array $lines): string {
 $text="BT /F1 12 Tf 48 790 Td 17 TL\n";
 foreach($lines as $line){$line=preg_replace('/[^\x20-\x7E]/',' ',(string)$line);foreach(explode("\n",wordwrap($line,86,"\n",true))as $part){$safe=str_replace(['\\','(',')'],['\\\\','\\(','\\)'],$part);$text.='('.$safe.") Tj T*\n";}}
 $text.="ET\n";
 $objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Length '.strlen($text)." >>\nstream\n".$text.'endstream'];
 $pdf="%PDF-1.4\n";$offsets=[0];foreach($objects as $i=>$object){$offsets[]=strlen($pdf);$pdf.=($i+1)." 0 obj\n".$object."\nendobj\n";}$xref=strlen($pdf);$pdf.="xref\n0 6\n0000000000 65535 f \n";foreach(array_slice($offsets,1)as $offset)$pdf.=sprintf("%010d 00000 n \n",$offset);return $pdf."trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n".$xref."\n%%EOF\n";
}
function demo_attachment(int $rid,int $uid,string $name,array $lines,string $visibility,string $created,array &$files): int {
 $bytes=demo_pdf_bytes($lines);$stored=bin2hex(random_bytes(24)).'.pdf';$path=ROOT.'/storage/uploads/'.$stored;
 $files[]=$path;
 if(file_put_contents($path,$bytes,LOCK_EX)!==strlen($bytes))throw new RuntimeException('Cannot save the demonstration document.');
 @chmod($path,0600);
 return insert('attachments',['request_id'=>$rid,'user_id'=>$uid,'original_name'=>$name,'stored_name'=>$stored,'mime'=>'application/pdf','size_bytes'=>strlen($bytes),'sha256'=>hash('sha256',$bytes),'visibility'=>$visibility,'created_at'=>$created]);
}
function demo_data_seed(string $password,array $admin): void {
 $data=json_decode((string)file_get_contents(ROOT.'/app/demo_dataset.json'),true,512,JSON_THROW_ON_ERROR);
 $files=[];$manifest=['dataset'=>'CivicFlow 2026.1','loaded_at'=>now(),'loaded_by'=>(int)$admin['id'],'user_ids'=>[],'request_ids'=>[],'attachment_ids'=>[],'created_department_ids'=>[],'created_service_ids'=>[],'published_service_ids'=>[],'announcement_ids'=>[]];
 db()->beginTransaction();try{
  foreach(['citizen','officer','department_head','auditor','communications']as $role)if(!row('SELECT role_key FROM roles WHERE role_key=? AND active=1',[$role]))throw new InvalidArgumentException('The '.$role.' role must be active before loading. Existing permissions are retained.');
  foreach($data['users']as $account)if(row('SELECT id FROM users WHERE email=?',[$account['email']]))throw new InvalidArgumentException('A demonstration email address already exists. Existing accounts are retained; ask the administrator to resolve the conflict before loading.');
  $depts=[];foreach($data['departments']as $d){$existing=row('SELECT * FROM departments WHERE code=?',[$d['code']]);if($existing)$depts[$d['code']]=(int)$existing['id'];else{$id=insert('departments',$d);$depts[$d['code']]=$id;$manifest['created_department_ids'][]=$id;}}
  $services=[];foreach($data['services']as $s){$department=$depts[$s['department']];$existing=row('SELECT * FROM services WHERE slug=?',[$s['slug']]);if($existing){if($existing['kind']!==$s['kind']||(int)$existing['department_id']!==$department)throw new InvalidArgumentException('The starter service '.$s['slug'].' has a different type or department. Resolve the catalogue conflict before loading.');if(!$existing['active']){sql('UPDATE services SET active=1 WHERE id=?',[$existing['id']]);$manifest['published_service_ids'][]=(int)$existing['id'];}$services[$s['slug']]=array_merge($existing,['active'=>1]);}else{$id=insert('services',['department_id'=>$department,'title'=>$s['title'],'slug'=>$s['slug'],'kind'=>$s['kind'],'description'=>$s['kind']==='permit'?'Submit an application with supporting documents for departmental review.':'Report a community issue and follow the department response.','requirements'=>$s['requirements'],'fee'=>0,'sla_hours'=>$s['sla_hours'],'active'=>1]);$services[$s['slug']]=row('SELECT * FROM services WHERE id=?',[$id]);$manifest['created_service_ids'][]=$id;}}
  $hash=password_hash($password,PASSWORD_DEFAULT);$citizens=[];$officers=[];$heads=[];$auditor=0;$communications=0;
  foreach($data['users']as $account){$department=$account['department']?$depts[$account['department']]:null;$id=insert('users',['name'=>$account['name'],'email'=>$account['email'],'phone'=>'','password_hash'=>$hash,'role'=>$account['role'],'department_id'=>$department,'status'=>'active','email_verified_at'=>now(),'notify_email'=>0,'notify_sms'=>0,'created_at'=>date('Y-m-d H:i:s',time()-30*86400)]);$manifest['user_ids'][]=$id;if($account['role']==='citizen')$citizens[]=$id;elseif($account['role']==='officer')$officers[$department][]=$id;elseif($account['role']==='department_head')$heads[$department]=$id;elseif($account['role']==='auditor')$auditor=$id;else $communications=$id;}
  $batch=strtoupper(bin2hex(random_bytes(3)));
  foreach($data['requests']as $i=>$case){
   $svc=$services[$case['service']];$status=$case['status'];$uid=$citizens[$case['citizen']];$dept=(int)$svc['department_id'];$officer=$officers[$dept][$case['officer_index']];$createdTs=time()-(int)$case['age_hours']*3600;$created=date('Y-m-d H:i:s',$createdTs);$stamp=fn(int $h)=>date('Y-m-d H:i:s',$createdTs+$h*3600);$closed=in_array($status,FINAL_STATUSES,true);$updated=$stamp($status==='draft'||$status==='submitted'?0:($closed?12:9));$reference='GOV-'.($svc['kind']==='permit'?'PER':'CMP').'-'.date('Y').'-DEMO3'.str_pad((string)($i+1),3,'0',STR_PAD_LEFT).'-'.$batch;
   $rid=insert('requests',['reference'=>$reference,'access_token'=>strtoupper(bin2hex(random_bytes(8))),'user_id'=>$uid,'service_id'=>$svc['id'],'department_id'=>$dept,'assigned_to'=>$status==='draft'?null:$officer,'kind'=>$svc['kind'],'subject'=>$case['subject'],'description'=>$case['description'],'location'=>$case['location'],'state_name'=>$case['state_name'],'organisation'=>$case['organisation'],'priority'=>$case['priority'],'status'=>$status,'due_at'=>$status==='draft'?null:$stamp((int)$svc['sla_hours']),'closed_at'=>$closed?$updated:null,'version'=>$status==='draft'||$status==='submitted'?1:3,'created_at'=>$created,'updated_at'=>$updated]);$manifest['request_ids'][]=$rid;
   $history=[];$history[]=['actor'=>$uid,'from'=>'','to'=>$status==='draft'?'draft':'submitted','message'=>$status==='draft'?'Application saved while the remaining supporting documents are prepared.':'Request submitted with the location and supporting information.','visibility'=>'public','date'=>$created];
   if(!in_array($status,['draft','submitted','withdrawn'],true))$history[]=['actor'=>$officer,'from'=>'submitted','to'=>'in_review','message'=>'The request has been assigned to our department. I am checking the information provided and the next action required.','visibility'=>'public','date'=>$stamp(4)];
   if($status==='needs_information')$history[]=['actor'=>$officer,'from'=>'in_review','to'=>$status,'message'=>$svc['kind']==='permit'?'Please add a clearer copy of the premises or venue evidence and confirm that the dates and address match the application. Reply here with the revised document.':'Please confirm the nearest landmark and whether the issue affects both sides of the access road. A recent site photograph would help us locate it.','visibility'=>'public','date'=>$stamp(8)];
   if($status==='resolved')$history[]=['actor'=>$officer,'from'=>'in_review','to'=>$status,'message'=>match($case['service']){'road-maintenance'=>'The blocked section was cleared and the surface reinstated. The department recorded a follow-up inspection; please reopen the complaint if the obstruction returns.','street-lighting'=>'The faulty lamp and connection were replaced. The maintenance team recorded an evening check of the lighting circuit.','waste-collection'=>'The missed collection was completed and the affected collection point was cleared. Please report the same location if the problem recurs.','environmental-nuisance'=>'The site operator was contacted and the source of the reported disturbance was addressed. The department recorded a follow-up visit.',default=>'The planning concern was reviewed. The department has provided the requested clarification and recorded the site review.'},'visibility'=>'public','date'=>$stamp(12)];
   if($status==='approved')$history[]=['actor'=>$officer,'from'=>'in_review','to'=>$status,'message'=>'The submitted plan and supporting records meet the requirements of this demonstration case. The application is approved for the stated activity. This is a fictional approval with no legal effect.','visibility'=>'public','date'=>$stamp(12)];
   if($status==='rejected')$history[]=['actor'=>$officer,'from'=>'in_review','to'=>$status,'message'=>$case['service']==='event-sanitation'?'The submitted waste management plan does not provide enough collection capacity for the proposed attendance. Prepare a revised plan before making a new application.':'The application could not be approved because the premises evidence does not establish the applicant right to use the site. A new application can be made with corrected evidence.','visibility'=>'public','date'=>$stamp(12)];
   if($status==='withdrawn')$history[]=['actor'=>$uid,'from'=>'submitted','to'=>$status,'message'=>'I am withdrawing this request because the location or proposed activity has changed. I will submit a new request if further assistance is needed.','visibility'=>'public','date'=>$stamp(12)];
   if(!in_array($status,['draft','submitted','withdrawn'],true))$history[]=['actor'=>$officer,'from'=>$closed?'in_review':$status,'to'=>$closed?'in_review':$status,'message'=>'Internal review: location checked against the submitted description. The allocated team should retain the site review note and confirm the outcome before closure.','visibility'=>'internal','date'=>$stamp(9)];
   usort($history,fn($a,$b)=>strcmp($a['date'],$b['date']));
   sql('UPDATE requests SET version=? WHERE id=?',[count($history),$rid]);
   foreach($history as $event){insert('events',['request_id'=>$rid,'actor_id'=>$event['actor'],'from_status'=>$event['from'],'to_status'=>$event['to'],'message'=>$event['message'],'visibility'=>$event['visibility'],'created_at'=>$event['date']]);insert('audit_logs',['actor_id'=>$event['actor'],'action'=>'demo.request.'.($event['visibility']==='internal'?'internal_note':$event['to']),'entity_id'=>$rid,'metadata'=>json_encode(['demonstration'=>true,'reference'=>$reference,'from'=>$event['from'],'to'=>$event['to']]),'ip_address'=>'Demonstration fixture','created_at'=>$event['date']]);}
   if($status!=='draft'&&($svc['kind']==='permit'||$i%3===0))$manifest['attachment_ids'][]=demo_attachment($rid,$uid,$svc['kind']==='permit'?'application-supporting-note.pdf':'site-observation-note.pdf',['CIVICFLOW DEMONSTRATION DOCUMENT','Fictional supporting evidence - no legal or identity value.','Request: '.$reference,'Subject: '.$case['subject'],'Location: '.$case['location'],'Prepared for: '.$case['organisation'],'This document describes an illustrative site or application record.','It does not contain genuine identification, ownership proof or official signatures.','The reviewing department must use its actual requirements for a live application.'],'public',$created,$files);
   if($status==='in_review'&&$case['officer_index']===1)$manifest['attachment_ids'][]=demo_attachment($rid,$officer,'internal-review-note.pdf',['CIVICFLOW DEMONSTRATION DOCUMENT','Staff-only illustrative review note.','Request: '.$reference,'Department review checklist: location, description and supporting record.','Further action: confirm the next review step with the assigned officer.','This note is fictional and must remain inside the authorised staff workspace.'],'internal',$stamp(8),$files);
   if($status!=='draft'){
    insert('notifications',['user_id'=>$uid,'request_id'=>$rid,'title'=>'Request '.label($status),'body'=>$reference.': '.($closed?'Your department has recorded the outcome. Open the request to review it.':'Your request is in the service review process. Open the record for the latest update.'),'link'=>'requests/'.$rid,'read_at'=>$i%3===0?$updated:null,'created_at'=>$updated]);
    if(!$closed)insert('notifications',['user_id'=>$officer,'request_id'=>$rid,'title'=>'Department case assigned','body'=>$reference.': '.$case['subject'],'link'=>'requests/'.$rid,'read_at'=>null,'created_at'=>$created]);
    $owner=$data['users'][$case['citizen']];$body='DEMONSTRATION RECORD - NOT SENT' ."\n\n".'Hello '.$owner['name'].', your request '.$reference.' is '.strtolower(label($status)).'. Open your account to read the service update. This outbox example has no delivery attempt.';
    insert('outbox',['user_id'=>$uid,'request_id'=>$rid,'channel'=>'email','recipient'=>$owner['email'],'subject'=>'Service update: '.$reference,'body'=>$body,'html_body'=>'<h2>Demonstration notification</h2><p>'.nl2br(e($body)).'</p>','template_key'=>'service_update','state'=>'cancelled','attempts'=>0,'last_error'=>'Demonstration fixture. Delivery intentionally cancelled; no provider attempt.','provider_id'=>'','created_at'=>$updated]);
   }
   if($case['feedback']!==null)insert('feedback',['request_id'=>$rid,'user_id'=>$uid,'rating'=>$case['feedback'],'comment'=>$case['feedback']>=4?'The recorded updates made it easier to understand the review and the final outcome.':'The issue was addressed, but I would have appreciated an earlier progress update.','created_at'=>$stamp(16)]);
  }
  foreach($heads as $dept=>$head)insert('notifications',['user_id'=>$head,'request_id'=>null,'title'=>'Department review queue prepared','body'=>'The demonstration queue contains open cases, decisions and supporting records. Review assignments and service targets in your department workspace.','link'=>'reports','read_at'=>null,'created_at'=>now()]);
  foreach([[$auditor,'Oversight review prepared','Read-only case records, audit activity and reports are available.','admin/audit'],[$communications,'Service communications prepared','Review the cancelled notification examples, templates and service notices.','admin/outbox']]as $note)insert('notifications',['user_id'=>$note[0],'request_id'=>null,'title'=>$note[1],'body'=>$note[2],'link'=>$note[3],'read_at'=>null,'created_at'=>now()]);
  foreach($data['announcements']as $i=>$notice)$manifest['announcement_ids'][]=insert('announcements',['title'=>$notice['title'],'body'=>$notice['body'],'active'=>1,'created_at'=>date('Y-m-d H:i:s',time()-$i*86400)]);
  set_setting('demo_dataset_mode','1');set_setting('demo_dataset_v103',json_encode($manifest,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE));set_setting('project_version','1.0.4');audit('demo.dataset_loaded',null,['version'=>$data['version'],'accounts'=>count($manifest['user_ids']),'requests'=>count($manifest['request_ids']),'external_delivery_attempts'=>0]);db()->commit();
 }catch(Throwable $error){if(db()->inTransaction())db()->rollBack();foreach($files as $file)@unlink($file);throw $error;}
}
